const $=s=>document.querySelector(s),M=$('#main');
const R=[['home','Home','🏠'],['checkin','Daily Check-in','🌷'],['explore','Explore','✨'],['insights','Insights','📊'],['journey','My Journey','🌱'],['mindi','Mindi','💬'],['settings','Settings','⚙️']],NM2={meditate:'explore',play:'explore',sounds:'explore',focus:'explore',night:'explore',journal:'explore',plan:'explore',progress:'journey'};let SUB;const CLN=[];
const nav=a=>R.map(r=>`<a href="#${r[0]}" class="${a==r[0]?'on':''}"><span>${r[2]}</span>${r[1]}</a>`).join('');
const lv=r=>r<35?['Low','var(--ok)']:r<65?['Moderate','var(--mid)']:['Elevated','var(--hi)'];
const bars=f=>f.map(x=>`<div class="sp"><div class="row sm"><span>${x[0]}</span><b>${x[1]}%</b></div><div class="bar"><b data-w="${x[1]}"></b></div></div>`).join('');
const tip=`<span class="tip" tabindex="0">i<span>These are wellness indicators based on your self-reported patterns. They are not medical diagnoses.</span></span>`;
function ring(v){const c=2*Math.PI*52;return `<svg viewBox="0 0 120 120" width="190" height="190"><defs><linearGradient id="rg"><stop offset="0" stop-color="#4fd1c5"/><stop offset="1" stop-color="#a78bfa"/></linearGradient></defs><circle cx="60" cy="60" r="52" fill="none" stroke="var(--line)" stroke-width="9"/><circle cx="60" cy="60" r="52" fill="none" stroke="url(#rg)" stroke-width="9" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c}" transform="rotate(-90 60 60)" style="transition:stroke-dashoffset 1.4s ease" data-off="${c*(1-v/100)}"/><text x="60" y="64" text-anchor="middle" style="font:700 28px Poppins;fill:var(--tx)" data-count="${v}">0</text><text x="60" y="80" text-anchor="middle" style="font-size:8px">/ 100</text></svg>`}
function chart(S,o={}){const W=300,H=o.h||130,all=S.flatMap(s=>s.d),mn=o.min??Math.min(...all)*.9,mx=o.max??Math.max(...all)*1.05,n=S[0].d.length,X=i=>8+i*(W-16)/(n-1),Y=v=>H-14-(v-mn)/(mx-mn)*(H-26);
let g=[0,1,2,3].map(i=>`<line x1="0" x2="${W}" y1="${6+i*(H-20)/3}" y2="${6+i*(H-20)/3}" stroke="var(--line)"/>`).join('');
const body=S.map((s,k)=>{if(o.bar){const bw=(W-16)/n*.6;return s.d.map((v,i)=>`<rect x="${X(i)-bw/2}" y="${Y(v)}" width="${bw}" height="${H-14-Y(v)}" rx="3" fill="${s.c}" opacity=".85"><animate attributeName="height" from="0" to="${H-14-Y(v)}" dur=".8s"/></rect>`).join('')}
const p=s.d.map((v,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)).join(' ');return (o.area?`<path d="${p} L${X(n-1)} ${H-14} L${X(0)} ${H-14}Z" fill="${s.c}" opacity=".18"/>`:'')+`<path d="${p}" fill="none" stroke="${s.c}" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" pathLength="1" stroke-dasharray="1" stroke-dashoffset="1"><animate attributeName="stroke-dashoffset" from="1" to="0" dur="1.1s" fill="freeze"/></path>`}).join('');
return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${o.label||'chart'}">${g}${body}<text x="8" y="${H-2}">14 days ago</text><text x="${W-8}" y="${H-2}" text-anchor="end">Today</text></svg>`}
const goBtns=`<a class="btn" href="#checkin">Start Today's Check-in</a> <a class="btn s" href="#insights">Explore Insights</a>`;
const recs=[['🌙','Sleep','Try maintaining a consistent sleep schedule tonight.','10 min','Easy'],['📚','Study','Break your largest task into 25–45 minute focused sessions.','45 min','Medium'],['🧘','Reset','Try a 5-minute breathing exercise.','5 min','Easy','#breathe'],['🚶','Movement','Take a short walk between study sessions.','15 min','Easy'],['🤍','Connection','Send a kind message to a friend or classmate.','5 min','Easy']];
const P={
home(){const me=authService.getCurrentUser()||{name:'Aarav'};const rh=(l,ic,t,d,u,mx)=>{const p=(d-t)/t*100;return `<div class="card"><div class="row"><b>${ic} ${l}</b><span class="pill">${Math.abs(p).toFixed(1)}% ${p<0?'below':'above'} baseline</span></div><div class="trk sp"><b data-w="${d/mx*100}"></b><i style="left:${t/mx*100}%"></i></div><div class="row sm mut sp"><span>Typical: ${t}${u}</span><span>Today: <b style="color:var(--dk)">${d}${u}</b></span></div></div>`};
return `<div class="pg"><div class="row" style="flex-wrap:wrap;gap:16px"><div><h1 style="font-size:clamp(26px,4vw,38px)">Good morning, ${me.name} 🌷</h1><p class="mut" style="margin:6px 0 0">Let's take a moment to check in with yourself.</p></div><div class="say">${mindi(48)}<span class="sm">Let's check in with yourself today. ♡</span></div></div>
<div class="g g2 sp"><div class="card" style="background:linear-gradient(135deg,#fff,#f6f0ff)"><h3>Your Wellness Snapshot</h3><div class="row" style="flex-wrap:wrap;justify-content:center;gap:20px;margin-top:6px">${ring(68)}<div><span class="badge">WELLNESS SCORE</span><p class="mut" style="max-width:220px">Your current pattern is slightly different from your usual routine.</p><a class="btn sm2" href="#checkin">Start today's check-in</a></div></div></div>
<div class="card"><h3>Today at a glance</h3><div class="snap sp"><div><span class="mut sm">Sleep</span><b>6.2 hrs</b></div><div><span class="mut sm">Energy</span><b>5/10</b></div><div><span class="mut sm">Mood</span><b>6/10</b></div><div><span class="mut sm">Focus</span><b>5/10</b></div><div><span class="mut sm">Screen Time</span><b>6.8 hrs</b></div><div><span class="mut sm">Academic Load</span><b>High</b></div></div></div></div>
<div class="card sp"><div class="row" style="flex-wrap:wrap"><h3>Current Wellness Pattern</h3><span class="chip" style="background:var(--yl)">Moderate</span></div><p class="mut">Some parts of your current routine have changed compared with your usual pattern.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><span class="chip" style="background:var(--pe)">Academic workload ↑</span><span class="chip" style="background:var(--sky)">Sleep ↓</span><span class="chip" style="background:var(--sage)">Recovery time ↓</span></div><div class="say sp" style="box-shadow:none;background:#faf6ff">${mindi(40)}<span class="sm">I noticed your routine has changed a little. Would you like to try a short breathing exercise? <a href="#breathe" style="color:var(--dk);font-weight:600">Breathe with me →</a></span></div></div>
<h2 class="sp" style="font-size:24px">Your Personal Rhythm 🌱</h2><p class="mut">Mindora learns your usual routine over time so it can highlight meaningful changes in your own pattern.</p>
<div class="g g4">${rh('Sleep','😴',7.1,6.2,' hrs',10)}${rh('Study','📚',5.4,7.5,' hrs',10)}${rh('Mood','🌤️',7.2,6,'/10',10)}</div>
<div class="card sp"><div class="row"><h3>What's influencing your current pattern?</h3>${tip}</div>${bars(factors)}</div>
<div class="card sp" style="background:linear-gradient(160deg,#fff,#f3fbf4)"><div class="row" style="flex-wrap:wrap"><h3>Today's Mindora 🌷</h3><span class="badge">Based on your recent pattern</span></div><div class="g g4 sp">${recEngine(CTX2,3).map((r,i)=>`<a class="cat" href="${r.route}" style="background:${['var(--sky)','var(--yl)','var(--pe)'][i]}"><span class="e">${r.icon}</span><b>${r.title}</b></a>`).join('')}</div><details class="sp sm"><summary style="cursor:pointer;color:var(--dk);font-weight:600">Why am I seeing these?</summary><p class="mut">These suggestions are based on your recent self-reported routine and are intended as general wellness activities.</p></details></div><h2 class="sp" style="font-size:22px">Today's gentle plan</h2><div class="g g4 sp">${recs.map((r,n)=>`<div class="card" style="background:${['var(--lav)','var(--yl)','var(--sky)','var(--sage)','var(--pk)'][n]}"><div style="font-size:28px">${r[0]}</div><h3>${r[1]}</h3><p class="sm" style="color:var(--tx)">${r[2]}</p><div class="row"><span class="pill">${r[3]}</span><a class="btn sm2" href="${r[5]||'#plan'}">Start</a></div></div>`).join('')}</div></div>`},
landing(){return `${pubhdr()}<section class="hero pg"><div><span class="badge">YOUR PERSONAL WELLNESS COMPANION</span><h1>Make yourself a priority. <span style="color:#e58fb0">♡</span></h1><p class="mut" style="font-size:17px;max-width:480px">Understand your daily patterns, build healthier routines, and give yourself a little more space to breathe.</p><div class="sp"><a class="btn" href="#signup">Get Started</a> <a class="btn s" href="#login">Log in</a></div><div class="say sp" style="max-width:430px">${mindi(48)}<span class="sm">Hi, I'm Mindi! Let's check in with yourself today. ♡</span></div></div><div style="text-align:center">${heroSvg()}</div></section><div class="g g4">${[['🌷','Gentle daily check-ins','A few friendly sliders. No right or wrong answers.','var(--pk)'],['🌱','Your Personal Rhythm','Mindora learns your usual routine and highlights meaningful changes.','var(--sage)'],['☁️','Small, kind plans','Little recovery habits that fit around your studies.','var(--sky)']].map(c=>`<div class="card" style="background:${c[3]}"><div style="font-size:28px">${c[0]}</div><h3>${c[1]}</h3><p class="sm" style="margin:6px 0 0">${c[2]}</p></div>`).join('')}</div><p class="sm mut sp" style="text-align:center">Mindora is a wellness support tool, not a medical diagnostic system.</p>`},
login(){return `${pubhdr()}<div class="auth pg"><div class="card" style="padding:36px"><h2>Welcome back ♡</h2><p class="mut">Good to see you again.</p><label class="q">Email</label><input id="em" type="email" placeholder="you@school.edu"><label class="q">Password</label><input id="pw" type="password" placeholder="Your password"><div class="row sp sm"><label><input type="checkbox" id="rm" checked> Remember me</label><a href="#login" id="fg" style="color:var(--dk)">Forgot password?</a></div><p id="er" class="sm" style="color:var(--hi);min-height:22px"></p><button class="btn" id="lg" style="width:100%">LOGIN</button><button class="btn s" id="dm" style="width:100%;margin-top:10px">Try the demo account</button><p class="mut sm" style="text-align:center">New to Mindora?</p><a class="btn s" style="width:100%;text-align:center" href="#signup">CREATE ACCOUNT</a></div><div style="text-align:center">${heroSvg()}</div></div>`},
signup(){return `${pubhdr()}<div class="auth pg"><div class="card" style="padding:36px"><h2>Let's get to know you 🌷</h2><p class="mut">Just the basics — nothing sensitive.</p><label class="q">Name</label><input id="nm" type="text" placeholder="Your name"><label class="q">Email</label><input id="em" type="email" placeholder="you@school.edu"><label class="q">Password</label><input id="pw" type="password" placeholder="At least 6 characters"><label class="q">Confirm password</label><input id="p2" type="password"><p id="er" class="sm" style="color:var(--hi);min-height:22px"></p><button class="btn" id="su" style="width:100%">CREATE ACCOUNT</button><p class="mut sm" style="text-align:center">Already have an account? <a href="#login" style="color:var(--dk)">Log in</a></p></div><div style="text-align:center">${heroSvg()}</div></div>`},
mindi(){const me=authService.getCurrentUser()||{name:'Aarav'};return `<div class="pg" style="max-width:760px;margin:auto"><h2>Mindi 🌱</h2><p class="mut">Your little wellness companion</p>
<div class="card" style="background:linear-gradient(160deg,#e6f5ea,#f3edff);text-align:center"><div style="display:flex;justify-content:center;align-items:flex-end;gap:10px;flex-wrap:wrap"><div id="mh">${mindi(150,MS.m)}</div><div class="bub" style="max-width:260px;text-align:left">Hey ${me.name} ♡<br>How are you feeling today?</div></div>
<div style="display:flex;gap:8px;margin-top:18px">${['😔|Low','😟|Stressed','😐|Okay','🙂|Good','😊|Great'].map((x,i)=>`<button class="mb" data-mood="${i}"><span>${x.split('|')[0]}</span>${x.split('|')[1]}</button>`).join('')}</div><div id="mr" class="bub sp" style="display:none;text-align:left"></div></div>
<div class="card sp" style="background:#fff"><b>Mindi's idea for you ♡</b><p style="margin:6px 0 12px">${planGuide()[0]}</p><div class="chips">${planGuide()[1].map(x=>`<a class="chipb" href="${x[1]}">${x[0]}</a>`).join('')}</div></div><div class="card sp" style="background:var(--yl)"><b>Something Mindi noticed 🌱</b><p style="margin:6px 0 12px">Your study time has been higher than your usual pattern this week, while your sleep has been a little lower.</p><a class="btn sm2" href="#insights">View My Insights</a></div>
<h3 class="sp">Today's little things 🌷</h3><div class="g sp" id="td"></div>
<div class="sp" style="text-align:center"><button class="btn" id="tk" style="font-size:16px;padding:16px 32px">Talk to Mindi 💬</button><div class="chips sp" style="justify-content:center"><a class="chipb" href="#insights">My Insights</a><a class="chipb" href="#plan">Wellness Plan</a><a class="chipb" href="#breathe">Breathing Exercise</a><a class="chipb" href="#checkin">Daily Check-in</a></div></div></div>`},
onboarding(){return `<div id="ob" class="pg" style="max-width:640px;margin:auto"></div>`},
checkin(){return `<div class="pg" id="ck" style="max-width:640px;margin:auto"></div>`},
insights(){const sel={w:1,r:1,m:0,e:0};return `<div class="pg"><h2>My Insights</h2><p class="mut">Your last 14 days of self-reported patterns.</p>
<div class="card sp"><div class="row" style="flex-wrap:wrap"><h3>Wellness Trend</h3><div id="tg" class="row" style="gap:6px;flex-wrap:wrap">${[['w','Wellness','#4fd1c5'],['r','Pressure pattern','#fb7185'],['m','Mood','#a78bfa'],['e','Energy','#5cc8ff']].map(t=>`<label class="pill" style="cursor:pointer"><input type="checkbox" data-k="${t[0]}" ${sel[t[0]]?'checked':''}> <span style="color:${t[2]}">●</span> ${t[1]}</label>`).join('')}</div></div><div id="tc" class="sp"></div></div>
<div class="g g2 sp"><div class="card"><h3>Sleep Trend (hrs)</h3>${chart([{d:D.sleep,c:'#a78bfa'}],{bar:1,min:0,max:9,label:'Sleep'})}</div><div class="card"><h3>Academic Workload (study hrs)</h3>${chart([{d:D.study,c:'#4fd1c5'}],{area:1,min:0,label:'Study'})}</div></div>
<div class="g g2 sp"><div class="card"><h3>Screen Time (hrs)</h3>${chart([{d:D.screen,c:'#5cc8ff'}],{label:'Screen'})}</div><div class="card"><h3>Pattern Summary</h3><p class="mut">Your recent data shows a pattern associated with lower wellness indicators on days when study time exceeds 8 hours, alongside shorter sleep. This is an observed pattern, not a cause.</p></div></div>
${baseline()}</div>`},
plan(){return `<div class="pg"><div class="row" style="flex-wrap:wrap"><div><h2>Wellness Plan</h2><p class="mut">Your focus this week</p></div><span class="pill" id="pc" style="font-size:14px"></span></div><div class="g sp" id="pl"></div></div>`},
progress(){const c=(t,a,b,ch,good)=>`<div class="card"><span class="mut sm">${t}</span><div class="big">${a}</div><div class="sm mut">Previous: ${b}</div><b style="color:var(--ok)">${ch}</b></div>`;return `<div class="pg"><h2>Progress</h2><p class="mut">Weekly overview</p><div class="g g4 sp">${c('Wellness score','68','61','+11%')}${c('Pressure pattern indicator','58%','67%','−9% (lower is better)')}<div class="card"><span class="mut sm">Biggest improvement</span><h3 class="sp">Sleep consistency</h3></div><div class="card"><span class="mut sm">Area to watch</span><h3 class="sp">Academic workload</h3></div></div>
<div class="g g2 sp">${[['Wellness trend',D.wellness,'#7fbf9f',{min:0,max:100}],['Sleep trend (hrs)',D.sleep,'#a897e0',{bar:1,min:0,max:9}],['Mood trend',D.mood,'#e58fb0',{min:0,max:10}],['Energy trend',D.energy,'#e0a04f',{min:0,max:10}],['Study pattern (hrs)',D.study,'#8cc8e8',{area:1,min:0}],['Screen time (hrs)',D.screen,'#a897e0',{}]].map(c=>`<div class="card"><h3>${c[0]}</h3>${chart([{d:c[1],c:c[2]}],c[3])}</div>`).join('')}</div></div>`},
journal(){return `<div class="pg" style="max-width:760px;margin:auto"><h2>How was your day? 💭</h2><p class="mut">Private to you.</p><div class="chips sp">${QP.map(q=>`<button class="chipb alt" data-qp>${q}</button>`).join('')}<button class="chipb" id="rp">Give me a reflection prompt</button></div><div class="card sp"><textarea id="jt" placeholder="Write anything you'd like to remember..."></textarea><div class="row sp"><select id="jm" style="width:auto"><option value="6">Mood: 6</option><option>3</option><option>5</option><option>7</option><option>9</option></select><button class="btn" id="js">Save Entry</button></div></div>
<div class="card sp" style="border-color:var(--vio)"><span class="badge">AI-generated reflection</span><p id="rf">Your recent entries frequently mention academic workload. You might consider scheduling a few short recovery breaks this week.</p></div><div class="g sp" id="je"></div></div>`},
settings(){const o=t=>`<div class="card row"><span>${t}</span><span class="pill">Configure</span></div>`;return `<div class="pg" style="max-width:720px;margin:auto"><h2>Settings</h2><div class="g sp">${['Profile','Notifications','Privacy','Data preferences'].map(o).join('')}
<div class="card row"><span>Theme</span><span class="pill">Soft pastel</span></div>
<div class="card row"><span>Export my data</span><button class="btn s sm2" data-cf="export">Export</button></div><div class="card row"><span>Delete my wellness data</span><button class="btn s sm2" data-cf="delete" style="color:var(--hi)">Delete</button></div><div class="card row"><span>Sign out</span><button class="btn s sm2" data-cf="signout">Sign out</button></div><a href="#support" class="card" style="text-decoration:none;color:inherit">Get Support →</a></div></div>`},
support(){return `<div class="pg" style="max-width:720px;margin:auto"><h2>Get Support</h2><p class="mut">Mindora is a wellness support tool, not a medical diagnostic system.</p><div class="g sp">${[['Talk to someone you trust','A friend, family member or mentor.'],['Contact a counselor','Your campus or school counseling service.'],['Contact a qualified mental-health professional','For ongoing or concerning difficulties.'],['Seek emergency help if you are in immediate danger','Contact your local emergency services right away.']].map((x,i)=>`<div class="card"><h3 style="font-size:17px">${x[0]}</h3><p class="mut sm" style="margin:6px 0">${x[1]}</p><span class="pill" id="sc${i}">Contact: configurable (SUPPORT_CONTACTS.${['trusted','counselor','professional','emergency'][i]})</span></div>`).join('')}</div></div>`}};
function baseline(){const b=[['Sleep','7.1 hrs','−18%'],['Study time','5.4 hrs','+32%'],['Screen time','5.8 hrs','+17%'],['Mood','7.2/10','−14%'],['Energy','7.0/10','−29%']];return `<div class="card sp"><h3>Your Personal Rhythm 🌱</h3><p class="mut">Mindora learns your normal routine over time so it can highlight meaningful changes in your own pattern.</p><div class="g g4">${b.map(x=>`<div class="snap" style="display:block"><div><span class="mut sm">Typical ${x[0].toLowerCase()}</span><b>${x[1]}</b><span class="${x[2][0]=='+'?'up':'dn'}">${x[2][0]=='+'?'↑':'↓'} ${x[2]} today</span></div></div>`).join('')}</div></div>`}
// ===== Check-in flow =====
const CK={s:1,v:{sleep:6.2,study:7.5,screen:6.8,active:20,load:8,pend:5,press:7,mood:6,energy:5,conc:5,social:6,typSleep:7,typStudy:5,typScreen:6,typMood:7,typEnergy:7}};
const fld=(k,t,min,max,st,u='')=>`<label class="q">${t}<span class="val" id="v_${k}">${CK.v[k]}${u}</span></label><input type="range" data-k="${k}" data-u="${u}" min="${min}" max="${max}" step="${st}" value="${CK.v[k]}">`;
function renderCk(){const el=$('#ck');if(!el)return;const s=CK.s;let b='';
if(s==1)b=fld('sleep','How was your sleep? 😴 (hours)',0,12,.5,' h')+fld('study','How much did you study? 📚 (hours)',0,14,.5,' h')+fld('screen','How much screen time did you have?',0,14,.5,' h')+fld('active','How much did you move today? 🚶 (min)',0,180,5,' min');
if(s==2)b=fld('load','How heavy does your workload feel? 🎒 (Low → High)',1,10,1)+fld('pend','Assignments currently pending',0,20,1)+fld('press','How would you rate your academic pressure? (Low → High)',1,10,1);
if(s==3)b=fld('mood','How is your mood? 🌤️',1,10,1,'/10')+fld('energy','How energetic do you feel? ⚡',1,10,1,'/10')+fld('conc','How focused do you feel? 🎯',1,10,1,'/10')+fld('social','How connected do you feel? 🤍',1,10,1,'/10');
if(s==4)return el.innerHTML=`<div class="card" style="text-align:center;padding:60px 20px">${mindi(84)}<h3 class="sp">Give me a moment while I look at your recent patterns...</h3><div class="spin" style="width:30px;height:30px;border-width:3px;margin-top:14px"></div></div>`;
if(s==5)return el.innerHTML=`<div class="say">${mindi(56)}<div><b>Thanks for checking in ♡</b><div class="mut sm">Your recent routine shows some changes worth paying attention to.</div></div></div><h2 class="sp">Your Wellness Insights 🌱</h2><div class="card sp" style="text-align:center"><span class="mut sm">Current Wellness Pattern</span><div class="big" style="color:var(--mid)">Moderate</div><p class="mut sm" style="margin:0">Some parts of your routine differ from your usual pattern (pressure indicator <b data-count="58">0</b>%).</p><div class="bar sp"><b class="risk" data-w="58"></b></div></div><div class="card sp"><h3>What's contributing most?</h3>${bars(factors.slice(0,4))}</div>
<div class="card sp"><h3>What changed from your usual pattern?</h3>${[['Sleep','↓ 1.3 hrs from your usual average','dn'],['Study time','↑ 2.1 hrs','up'],['Mood','↓ 1.2 points','dn'],['Screen time','↑ 1.4 hrs','up']].map(x=>`<div class="row sp"><span>${x[0]}</span><b class="${x[2]}">${x[1]}</b></div>`).join('')}</div>
<div class="card sp"><span class="mut sm">Recommended focus</span><h3>Recovery + workload balance</h3><a class="btn sp" href="#plan">View My Wellness Plan</a></div>`;
el.innerHTML=`<h2>How are you feeling today? 🌷</h2><p class="mut" style="margin-bottom:0">No right or wrong answers. This is just for you.</p><p class="sm mut">Step ${s} of 3 · ${['Daily Routine','Academic Pressure','Wellbeing'][s-1]}</p><div class="steps">${[1,2,3].map(i=>`<i class="${i<=s?'on':''}"></i>`).join('')}</div><div class="card">${b}<div class="row sp" style="margin-top:28px">${s>1?'<button class="btn s" id="pv">Back</button>':'<span></span>'}<button class="btn" id="nx">${s<3?'Continue':'Analyze My Check-in'}</button></div></div>`;
el.querySelectorAll('input').forEach(i=>i.oninput=()=>{CK.v[i.dataset.k]=+i.value;$('#v_'+i.dataset.k).textContent=i.value+i.dataset.u});
$('#nx').onclick=async()=>{if(s<3){CK.s++;renderCk()}else{CK.s=4;renderCk();await api.postCheckin(CK.v);CK.s=5;renderCk();anim()}};const p=$('#pv');if(p)p.onclick=()=>{CK.s--;renderCk()}}
// ===== Wellness ecosystem: services, rec engine, activities =====
const CTX2={sleep:6.2,study:7.5,screen:6.8,mood:6,energy:5,load:8}; // mock user state (from check-in)
const ACT={breathe:['🌬️','5-minute breathing reset','#breathe'],winddown:['🌙','Evening wind-down','#night'],move:['🚶','Short movement break','#plan'],focus:['📚','Balanced focus session','#focus'],waves:['🌊','Calm Waves','#play-waves'],screen:['📵','Screen break','#night'],sound:['🎧','Soundscape','#sounds'],reflect:['✍️','Gentle reflection','#journal'],support:['🤍','Talk to someone you trust','#support']};
// Rule-based recommender. Swap for GET /api/recommendations (ML) later — same return shape.
function recEngine(c,n=4){const r=[],A=(k,w)=>r.push([k,w]);
if(c.sleep<6){A('winddown','your sleep has been shorter than usual');A('breathe','a calm pause can support rest')}
if(c.study>8){A('focus','study stretches have been long');A('waves','a gentle break between sessions')}
if(c.energy<5){A('move','your energy feels lower');A('breathe','slow breathing is a gentle reset')}
if(c.mood<=4){A('reflect','a little reflection can help sort thoughts');A('support','you don\'t have to carry things alone')}
if(c.load>=8){A('focus','your academic workload feels high');A('breathe','a short recovery break')}
if(c.screen>7){A('screen','screen time is above your usual');A('sound','calming sounds can ease the switch-off')}
[['breathe','a calm pause for a busy day'],['winddown','your sleep is a bit below your usual'],['move','movement between study sessions'],['focus','structured, balanced study time'],['waves','a slow, pressure-free break']].forEach(x=>A(...x));
const seen={};return r.filter(x=>!seen[x[0]]&&(seen[x[0]]=1)).slice(0,n).map(x=>({k:x[0],icon:ACT[x[0]][0],title:ACT[x[0]][1],route:ACT[x[0]][2],why:'Because '+x[1]+'.'}))}
const JN={checkin:14,meditation:1,breathing:2,journal:2,focus:0,game:1},SP={rain:.3,ocean:0,forest:.2,fire:0,music:.2};
const tot=()=>Object.values(JN).reduce((a,b)=>a+b,0);
const track=t=>{JN[t]=(JN[t]||0)+1;return exploreService.saveActivityProgress(t)};
const FC=['#F8C8D8','#C9B8F2','#A9D4F0','#9fd8b4','#FFE08A'],ML=['😔 Low','😟 Stressed','😐 Okay','🙂 Good','😊 Great'],bk=v=>v<5?0:v<5.9?1:v<6.5?2:v<7.2?3:4;
const exploreService={getActivities:()=>wait(ACT,0),getRecommendations:()=>wait(recEngine(CTX2),0),saveActivityProgress:t=>wait({type:t,total:tot()},0),getMoodGarden:()=>wait(D.mood.map((m,i)=>({i,mood:bk(m),score:D.wellness[i]})),0),getJourney:()=>wait(JN,0),getSoundPreferences:()=>wait(SP,0)}; // → POST /api/activity, GET /api/recommendations …
// ----- Soundscape (Web Audio synth; set SND.files to real audio later) -----
const SND={ctx:null,g:{},on:0,vol:{...SP},files:{rain:null,ocean:null,forest:null,fire:null,music:null},K:{rain:.35,ocean:.6,forest:.25,fire:.7,music:.05},
init(){if(this.ctx)return;const c=this.ctx=new(window.AudioContext||window.webkitAudioContext)(),b=c.createBuffer(1,c.sampleRate*2,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
const mk=(t,f,l)=>{const s=c.createBufferSource();s.buffer=b;s.loop=true;const fl=c.createBiquadFilter();fl.type=t;fl.frequency.value=f;const g=c.createGain();g.gain.value=0;s.connect(fl);fl.connect(g);g.connect(c.destination);s.start();if(l){const o=c.createOscillator(),og=c.createGain();o.frequency.value=l;og.gain.value=f*.6;o.connect(og);og.connect(fl.frequency);o.start()}return g};
this.g={rain:mk('highpass',1200),ocean:mk('lowpass',450,.12),forest:mk('bandpass',2600,.3),fire:mk('lowpass',250,2)};const m=c.createGain();m.gain.value=0;m.connect(c.destination);[220,277.2,329.6].forEach(f=>{const o=c.createOscillator();o.frequency.value=f;o.connect(m);o.start()});this.g.music=m},
ap(){if(!this.ctx)return;for(const k in this.g)this.g[k].gain.setTargetAtTime(this.on?(this.vol[k]||0)*this.K[k]:0,this.ctx.currentTime,.3)},
play(){try{this.init();this.ctx.resume();this.on=1;this.ap()}catch(e){}},pause(){this.on=0;this.ap()},set(o){Object.assign(this.vol,o);this.ap()}};
const PRESETS={'Study Atmosphere':{rain:.3,ocean:0,forest:.2,fire:0,music:.2},'Evening Calm':{rain:0,ocean:.4,forest:0,fire:.3,music:.3},'Rainy Day':{rain:.6,ocean:0,forest:.1,fire:.2,music:.1},'Deep Focus':{rain:.4,ocean:0,forest:0,fire:0,music:.3}};
