const flowerSvg=(c,z=40)=>`<svg width="${z}" height="${z*1.5}" viewBox="0 0 40 60"><path d="M20 28v28" stroke="#8fc7a8" stroke-width="3" stroke-linecap="round"/><path d="M20 46q-10-2-12-10 10 0 12 10z" fill="#CDE8D5"/>${[0,72,144,216,288].map(a=>`<ellipse cx="20" cy="11" rx="6" ry="9" fill="${c}" transform="rotate(${a} 20 22)"/>`).join('')}<circle cx="20" cy="22" r="5" fill="#FFF0B8"/></svg>`;
const gardenHtml=()=>`<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:6px;background:linear-gradient(#f3fbf4,#dff1e4);border-radius:24px;padding:16px 10px 6px;text-align:center">${D.mood.map((m,i)=>`<button data-day="${i}" aria-label="Day ${i+1}" style="border:0;background:none;cursor:pointer">${flowerSvg(FC[bk(m)],38)}</button>`).join('')}</div><div id="dd" class="card sp sm mut">Tap a flower to see that day. 14 days of check-ins 🌷</div>`;
