const gmEnd=()=>track('game');
const GM={
waves(el){el.innerHTML='<canvas id="wv" width="640" height="340" style="width:100%;border-radius:20px;background:linear-gradient(#C8E7F5,#DCCFF5);touch-action:none"></canvas><div class="row sm mut" style="padding:10px"><span id="wd"></span><span id="wm"></span></div>';const c=$('#wv'),x=c.getContext('2d'),R=[],L=Array.from({length:6},(_,i)=>({x:Math.random()*640,y:40+Math.random()*260,s:.15+Math.random()*.2,p:i}));let n=0,id;
const dots=()=>$('#wd').innerHTML=Array.from({length:10},(_,i)=>`<span style="color:${i<n?'#7fbf9f':'#d9d3e6'}">●</span>`).join(' ')+' &nbsp;10 gentle ripples';dots();
c.onpointerdown=e=>{const b=c.getBoundingClientRect();R.push({x:(e.clientX-b.left)*640/b.width,y:(e.clientY-b.top)*340/b.height,r:4,a:.8});if(n<10&&++n==10){$('#wm').textContent='Nice. Take another slow breath. 🌱';gmEnd()}dots()};
(function f(){x.clearRect(0,0,640,340);L.forEach(l=>{l.x=(l.x+l.s)%660;x.fillStyle='#CDE8D5';x.beginPath();x.ellipse(l.x,l.y+Math.sin(l.x/40+l.p)*6,12,6,.5,0,6.28);x.fill()});R.forEach(r=>{r.r+=.8;r.a-=.006;x.strokeStyle=`rgba(255,255,255,${Math.max(r.a,0)})`;x.lineWidth=2.5;x.beginPath();x.arc(r.x,r.y,r.r,0,6.28);x.stroke()});while(R.length&&R[0].a<=0)R.shift();id=requestAnimationFrame(f)})();CLN.push(()=>cancelAnimationFrame(id))},
bloom(el){el.innerHTML=`<svg viewBox="0 0 200 200" width="240"><g id="bp" style="transform-origin:100px 100px;transition:transform 4s ease-in-out;transform:scale(.3)">${[0,45,90,135,180,225,270,315].map(a=>`<ellipse cx="100" cy="60" rx="14" ry="36" fill="#F8C8D8" transform="rotate(${a} 100 100)"/>`).join('')}</g><circle cx="100" cy="100" r="13" fill="#FFF0B8"/></svg><h3 id="bm">Press begin and follow along</h3><button class="btn" id="bg2">Begin</button>`;let n=0,T=[];const tm=(f,t)=>T.push(setTimeout(f,t));CLN.push(()=>T.forEach(clearTimeout));
const cy=()=>{if(n>=4){$('#bm').textContent='You made space for a little calm. 🌸';$('#bp').style.transform='scale(1)';gmEnd();$('#bg2').style.display='';return}n++;$('#bm').textContent='Breathe in';$('#bp').style.transform=`scale(${.3+n*.18}) rotate(0deg)`;tm(()=>{$('#bm').textContent='Breathe out';$('#bp').style.transform=`scale(${.3+n*.18-.05}) rotate(8deg)`;tm(cy,6000)},4000)};$('#bg2').onclick=e=>{n=0;e.target.style.display='none';cy()}},
stars(el){el.style.background='linear-gradient(#262b5c,#4b3f84)';el.style.color='#fff';el.innerHTML='<p id="sm" style="position:relative;z-index:2;margin-top:12px">Tap the drifting stars whenever you like. ✨</p>';let n=0;const mk=()=>{const b=document.createElement('button');b.className='star';b.textContent='✨';b.style.top=(15+Math.random()*70)+'%';b.style.animationDuration=(16+Math.random()*14)+'s';b.style.animationDelay=(-Math.random()*20)+'s';b.onclick=()=>{b.remove();n++;$('#sm').textContent=n>=5?'Keep going gently. ✨':'Caught one. ✨';if(n==5)gmEnd();mk()};el.append(b)};for(let i=0;i<10;i++)mk();CLN.push(()=>{el.style.background='';el.style.color=''})},
plant(el){const t=tot(),st=t>=25?'🌳':t>=12?'🪴':t>=5?'🌿':'🌱';el.innerHTML=`<div style="font-size:110px;margin-top:30px" class="float">${st}</div><h3>Your little wellness space is growing.</h3><p class="mut sm">It grows a little with each optional activity you try — meditation, breathing, journaling, focus, play. No streaks, no pressure.</p><a class="btn sm2" href="#explore">Find an activity</a>`},
bubbles(el){const P=['Relax your shoulders.','Take one slow breath.','Look away from the screen.','Drink some water.','Unclench your jaw.','Stretch your arms up.'];el.innerHTML='<h3 id="bt2" style="position:relative;z-index:2;margin-top:10px">Pop a bubble gently 🫧</h3>';const mk=()=>{const b=document.createElement('button');b.className='bb2';b.style.left=(5+Math.random()*80)+'%';b.style.top=(25+Math.random()*60)+'%';b.style.animationDelay=(-Math.random()*5)+'s';b.onclick=()=>{b.classList.add('pop');$('#bt2').textContent=P[Math.random()*P.length|0];setTimeout(()=>{b.remove();mk()},350)};el.append(b)};for(let i=0;i<6;i++)mk();},
puzzle(el){const S=['○','△','□','◇','✿','♡','★','☁'],C=['#F8C8D8','#C8E7F5','#CDE8D5','#FFF0B8','#DCCFF5','#FFDCC8','#F8C8D8','#C8E7F5'];const dk=[...S,...S].map((v,i)=>[v,C[i%8]]).sort(()=>Math.random()-.5);let a=null,lock=0,m=0;el.innerHTML=`<h3>Find the pairs, slowly 🧩</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;max-width:360px;margin:14px auto" id="pz">${dk.map((d,i)=>`<button class="mc" data-i="${i}">${d[0]}</button>`).join('')}</div><p id="pm" class="mut">No timer. Take your time.</p>`;
el.querySelectorAll('.mc').forEach(b=>b.onclick=()=>{if(lock||b.classList.contains('up')||b.classList.contains('ok'))return;b.classList.add('up');b.style.background=dk[b.dataset.i][1];if(!a){a=b;return}if(a.textContent==b.textContent){a.classList.add('ok');b.classList.add('ok');a=null;if(++m==8){$('#pm').textContent='Lovely. That was a calm one. ✨';gmEnd()}}else{lock=1;const q=a;a=null;setTimeout(()=>{[q,b].forEach(x=>{x.classList.remove('up');x.style.background=''});lock=0},800)}})}};
