meditate(){document.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>{const[i,j]=b.dataset.m.split('-'),m=MED[i][1][j];BR.dur=m[2]*60;BR.title=m[1];BR.kind='meditation';location.hash='#breathe'})},
