const MS={m:3},TD=[0,0,0,0],MR=[["Thanks for checking in with me. You don't have to fix everything right now. Let's take one small step together. ♡","#breathe","Take a tiny reset"],["Sounds like today feels a little heavy. Want to take a small reset with me?","#breathe","Breathe with me"],["Nice. Let's keep that steady feeling going. 🌱"],["That's lovely to hear! What helped you feel good today?","#journal","Write it down"],["Yay! Let's keep that energy going. ✨"]];
