// ===== Onboarding =====
const OB={s:1,g:[]};
function renderOb(){const el=$('#ob');if(!el)return;const s=OB.s,goals=['😴 Sleep better','🎒 Balance my workload','⚡ Feel more energized','🧘 Build calm routines','🤍 Stay connected'];
const b=s==1?fld('typSleep','Usually, how many hours do you sleep?',0,12,.5,' h')+fld('typStudy','How many hours do you usually study?',0,14,.5,' h')+fld('typScreen','Typical daily screen time?',0,14,.5,' h'):s==2?`<div class="g">${goals.map((x,i)=>`<button class="btn s" data-g="${i}" style="text-align:left;${OB.g.includes(i)?'background:var(--lav)':''}">${x}</button>`).join('')}</div>`:fld('typMood','On a typical day, how is your mood?',1,10,1,'/10')+fld('typEnergy','How energetic do you usually feel?',1,10,1,'/10')+'<p class="sm mut">Mindora uses this to learn your normal rhythm. You can change it anytime.</p>';
el.innerHTML=`<div class="say">${mindi(52)}<span>Welcome, ${(authService.getCurrentUser()||{name:''}).name}! A few gentle questions — no right or wrong answers. ♡</span></div><h2 class="sp">${['Tell us a little about your routine.','How would you like Mindora to support you?',"Let's create your personal baseline."][s-1]}</h2><div class="steps">${[1,2,3].map(i=>`<i class="${i<=s?'on':''}"></i>`).join('')}</div><div class="card">${b}<div class="row sp" style="margin-top:26px">${s>1?'<button class="btn s" id="pv">Back</button>':'<span></span>'}<button class="btn" id="nx">${s<3?'Continue':'Finish'}</button></div></div>`;
el.querySelectorAll('input[type=range]').forEach(i=>i.oninput=()=>{CK.v[i.dataset.k]=+i.value;$('#v_'+i.dataset.k).textContent=i.value+i.dataset.u});
el.querySelectorAll('[data-g]').forEach(x=>x.onclick=()=>{const i=+x.dataset.g;OB.g=OB.g.includes(i)?OB.g.filter(v=>v!=i):[...OB.g,i];renderOb()});
$('#nx').onclick=async()=>{if(s<3){OB.s++;renderOb()}else{await userService.saveProfile({baseline:{sleep:CK.v.typSleep,study:CK.v.typStudy,screen:CK.v.typScreen,mood:CK.v.typMood,energy:CK.v.typEnergy},goals:OB.g.map(i=>goals[i])});location.hash='#home'}};const p=$('#pv');if(p)p.onclick=()=>{OB.s--;renderOb()}}
