const plan=[['🌙 Improve sleep consistency','Your sleep dropped 1.3 hrs below baseline.','10 min','Easy',1],['📚 Balance academic workload','Study time has been above your usual range.','30 min','Medium',1],['🚶 Add physical activity','Activity is lower than your typical routine.','15 min','Easy',1],['🧘 Schedule recovery breaks','Little downtime between focus sessions recently.','5 min','Easy',0],['🤍 Reach out to someone you trust','A little connection can make a heavy week feel lighter.','20 min','Medium',0]];
