const ent=[['Today',6,'Had a difficult day because of assignments. Too many deadlines at once, but a walk helped a little.'],['2 days ago',7,'Felt more productive today. Short focus sessions worked well.'],['5 days ago',5,'Slept late again. Hard to concentrate in the afternoon.']];
