// ===== Orb (2D canvas; no WebGL needed → always has a fallback) =====
let raf,mx=0,my=0;function orb(){const c=$('#orb');if(!c)return;cancelAnimationFrame(raf);const x=c.getContext('2d'),S=600;c.width=c.height=S;const rm=matchMedia('(prefers-reduced-motion:reduce)').matches;const sp=1.15;
const pts=Array.from({length:110},()=>({a:Math.random()*6.28,r:.55+Math.random()*.4,s:(Math.random()*.4+.1)*sp,z:Math.random()}));
c.onmousemove=e=>{const b=c.getBoundingClientRect();mx=(e.clientX-b.left)/b.width-.5;my=(e.clientY-b.top)/b.height-.5};let t=0;
(function f(){t+=.012;x.clearRect(0,0,S,S);const cx=S/2+mx*40,cy=S/2+my*40+Math.sin(t)*10,R=170+Math.sin(t*1.3)*6;
let g=x.createRadialGradient(cx-50,cy-60,10,cx,cy,R);g.addColorStop(0,'#c7f7f0');g.addColorStop(.4,'#4fd1c5');g.addColorStop(.75,'#6b7be0');g.addColorStop(1,'#a78bfa');
x.shadowColor='rgba(92,200,255,.6)';x.shadowBlur=70;x.fillStyle=g;x.beginPath();x.arc(cx,cy,R,0,6.28);x.fill();x.shadowBlur=0;
g=x.createRadialGradient(cx,cy,R*.9,cx,cy,R*1.6);g.addColorStop(0,'rgba(120,140,255,.25)');g.addColorStop(1,'transparent');x.fillStyle=g;x.fillRect(0,0,S,S);
pts.forEach(p=>{p.a+=p.s*.01;const rr=R*(1.15+p.r*.6),px=cx+Math.cos(p.a)*rr,py=cy+Math.sin(p.a*1.2)*rr*.8;x.fillStyle=`rgba(190,235,255,${.25+p.z*.5})`;x.beginPath();x.arc(px,py,1.5+p.z*2.2,0,6.28);x.fill()});
if(!rm)raf=requestAnimationFrame(f)})()}
// ===== Helpers =====
