let bt;const BR={dur:90,title:'Breathing Garden 🌱',kind:'breathing'};
function breathe(){const dur=BR.dur,title=BR.title,kind=BR.kind;BR.dur=90;BR.title='Breathing Garden 🌱';BR.kind='breathing';const o=document.createElement('div');o.id='breathe';
const pet=[0,45,90,135,180,225,270,315].map(a=>`<ellipse cx="100" cy="46" rx="11" ry="24" fill="${a%90?'#F8C8D8':'#DCCFF5'}" transform="rotate(${a} 100 78)"/>`).join(''),pts=Array.from({length:10},(_,i)=>`<circle class="pt gt" data-a="${i*36}" cx="100" cy="78" r="3" fill="#fff" opacity="0"/>`).join('');
o.innerHTML=`<div id="bgl" style="position:absolute;inset:0;background:radial-gradient(circle at 50% 45%,#fff,transparent 70%);opacity:0;transition:opacity 4s;pointer-events:none"></div><div style="font-size:12px;letter-spacing:.14em;color:#667085;position:relative">${title.toUpperCase()} · 4 · 4 · 6</div><svg viewBox="0 0 200 200" width="min(320px,80vw)" style="position:relative;overflow:visible"><ellipse cx="100" cy="180" rx="60" ry="8" fill="#CDE8D5"/>${pts}<g id="lv" class="gt" style="transform-origin:100px 170px"><path d="M100 170C98 140 102 110 100 90" stroke="#8fc7a8" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M100 150q-34-4-40-30 30 2 40 30z" fill="#CDE8D5"/><path d="M100 138q34-4 40-30-30 2-40 30z" fill="#b9e0c6"/></g><g id="fl" class="gt" style="transform:scale(.6)">${pet}<circle cx="100" cy="78" r="13" fill="#FFF0B8"/></g></svg><h1 id="bi" style="letter-spacing:.02em;position:relative">Breathe in</h1><div class="ph" id="bt" style="font-size:22px;position:relative">00:00</div><div style="position:relative"><button class="btn" id="bp">Pause</button> <a class="btn s" href="#explore">Exit</a></div><p style="font-size:12px;color:#667085;max-width:340px;position:relative">A simple relaxation exercise for a calmer moment — not a medical treatment.</p>`;document.body.append(o);
let sec=0,run=1,ph=0,left=4;const cyc=[['Breathe in',4],['Hold',4],['Breathe out',6]],fl=$('#fl'),lv=$('#lv'),bg=$('#bgl');
const set=()=>{const d=cyc[ph][1]+'s';[fl,lv,bg,...o.querySelectorAll('.pt')].forEach(e=>e.style.transitionDuration=d);$('#bi').textContent=cyc[ph][0];if(ph==0){fl.style.transform='scale(1.25)';lv.style.transform='rotate(3deg)';bg.style.opacity=.7;o.querySelectorAll('.pt').forEach(e=>{const a=e.dataset.a*Math.PI/180;e.style.transform=`translate(${Math.cos(a)*70}px,${Math.sin(a)*70}px)`;e.style.opacity=.9})}if(ph==2){fl.style.transform='scale(.65)';lv.style.transform='rotate(-3deg)';bg.style.opacity=0;o.querySelectorAll('.pt').forEach(e=>{e.style.transform='none';e.style.opacity=0})}};set();
bt=setInterval(()=>{if(!run)return;sec++;$('#bt').textContent=String(sec/60|0).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec>=dur){clearInterval(bt);o.querySelector('h1').textContent='You gave yourself a few quiet minutes. 🌱';$('#bp').style.display='none';track(kind);return}if(--left<=0){ph=(ph+1)%3;left=cyc[ph][1];set()}},1000);$('#bp').onclick=e=>{run=!run;e.target.textContent=run?'Pause':'Resume'}}
